  8	/**
  9	 * Centralizes adjacency, target selection, and movement-related rules.
 10	 */
 11	public class MovementService
 12	{
 13	    private static final Class<? extends Organism> DEFAULT_FALLBACK_SPECIES = Grass.class;
 14	
 15	    private final RandomProvider randomProvider;
 16	    private final Map<Class<? extends Organism>, MovementRule> movementRules;
 17	
 18	    public MovementService(RandomProvider randomProvider)
 19	    {
 20	        this.randomProvider = randomProvider;
 21	        this.movementRules = Map.of(
 22	                Eagle.class,
 23	                new MovementRule(DEFAULT_FALLBACK_SPECIES, environment -> environment.getWeatherService().allowsEagleForaging())
 24	        );
 25	    }
 26	
 27	    public void moveOrganism(Organism organism, Location location)
 28	    {
 29	        organism.setLocation(location);
 30	    }
 31	
 32	    public List<Location> getAdjacentLocations(Field field, Location location)
 33	    {
 34	        assert location != null : "Null location passed to getAdjacentLocations";
 35	        List<Location> locations = new LinkedList<>();
 36	        int row = location.getRow();
 37	        int col = location.getCol();
 38	        for(int roffset = -1; roffset <= 1; roffset++) {
 39	            int nextRow = row + roffset;
 40	            if(nextRow >= 0 && nextRow < field.getDepth()) {
 41	                for(int coffset = -1; coffset <= 1; coffset++) {
 42	                    int nextCol = col + coffset;
 43	                    if(nextCol >= 0
 44	                            && nextCol < field.getWidth()
 45	                            && (roffset != 0 || coffset != 0)) {
 46	                        locations.add(new Location(nextRow, nextCol));
 47	                    }
 48	                }
 49	            }
 50	        }
 51	
 52	        Collections.shuffle(locations, randomProvider.getRandom());
 53	        return locations;
 54	    }
 55	
 56	    public List<Location> getFreeAdjacentLocations(Field field, Location location)
 57	    {
 58	        return getFreeAdjacentLocations(field, getAdjacentLocations(field, location));
 59	    }
 60	
 61	    public Location findFreeAdjacentLocation(Field field, Location location)
 62	    {
 63	        return firstOrNull(getFreeAdjacentLocations(field, location));
 64	    }
 65	
 66	    public List<Location> findAdjacentLocationsWithSpecies(Field field, Location location, Class<?> speciesClass)
 67	    {
 68	        return findAdjacentLocationsWithSpecies(field, getAdjacentLocations(field, location), speciesClass);
 69	    }
 70	
 71	    public List<Organism> findPotentialMates(Animal animal)
 72	    {
 73	        List<Organism> potentialMates = new ArrayList<>();
 74	        Field field = animal.getField();
 75	        if(field != null) {
 76	            for(Location location : getAdjacentLocations(field, animal.getLocation())) {
 77	                Object nearby = field.getObjectAt(location);
 78	                if(nearby instanceof Animal mate
 79	                        && mate.getClass().equals(animal.getClass())
 80	                        && mate.sex != animal.sex) {
 81	                    potentialMates.add(mate);
 82	                }
 83	            }
 84	        }
 85	        return potentialMates;
 86	    }
 87	
 88	    public List<Location> getRandomFreePatches(Field field, double rateOfGeneration)
 89	    {
 90	        List<Location> patches = getFreePatches(field);
 91	        List<Location> randomPatches = new ArrayList<>();
 92	        for(int i = 0; i < rateOfGeneration * patches.size() && !patches.isEmpty(); i++) {
 93	            Location selectedPatch = patches.get(randomProvider.getRandom().nextInt(patches.size()));
 94	            randomPatches.add(selectedPatch);
 95	            for(Location location : getAdjacentLocations(field, selectedPatch)) {
 96	                patches.remove(location);
 97	            }
 98	            patches.remove(selectedPatch);
 99	        }
100	        return randomPatches;
101	    }
102	
103	    public MovementDecision resolveAnimalMovement(Animal animal,
104	            Environment environment,
105	            List<Location> adjacentLocations)
106	    {
107	        MovementRule rule = getMovementRule(animal.getClass());
108	        if(rule.canForage(environment)) {
109	            MovementDecision foodTarget = findTarget(fieldOf(animal), adjacentLocations, animal.getDiet());
110	            if(foodTarget != null) {
111	                return foodTarget;
112	            }
113	        }
114	
115	        return resolveFallbackMovement(fieldOf(animal), adjacentLocations, rule);
116	    }
117	
118	    public MovementDecision resolveHunterMovement(Hunter hunter, List<Location> adjacentLocations)
119	    {
120	        MovementDecision preyTarget = findTarget(fieldOf(hunter), adjacentLocations, hunter.getDiet());
121	        if(preyTarget != null) {
122	            return preyTarget;
123	        }
124	
125	        return resolveFallbackMovement(fieldOf(hunter), adjacentLocations, getMovementRule(Hunter.class));
126	    }
127	
128	    private Field fieldOf(Organism organism)
129	    {
130	        return organism.getField();
131	    }
132	
133	    private MovementDecision resolveFallbackMovement(Field field,
134	            List<Location> adjacentLocations,
135	            MovementRule rule)
136	    {
137	        Location freeLocation = firstOrNull(getFreeAdjacentLocations(field, adjacentLocations));
138	        if(freeLocation != null) {
139	            return new MovementDecision(freeLocation, null, false);
140	        }
141	
142	        Location speciesFallback = pickRandomLocation(
143	                findAdjacentLocationsWithSpecies(field, adjacentLocations, rule.fallbackSpecies())
144	        );
145	        if(speciesFallback != null) {
146	            return new MovementDecision(speciesFallback, null, false);
147	        }
148	
149	        return new MovementDecision(null, null, true);
150	    }
151	
152	    private MovementDecision findTarget(Field field,
153	            List<Location> adjacentLocations,
154	            Set<Class<? extends Organism>> targetSpecies)
155	    {
156	        for(Location location : adjacentLocations) {
157	            Object occupant = field.getObjectAt(location);
158	            if(occupant instanceof Organism organism && targetSpecies.contains(occupant.getClass())) {
159	                if(organism.isAlive()) {
160	                    return new MovementDecision(location, organism, false);
161	                }
162	                return new MovementDecision(location, null, false);
163	            }
164	        }
165	        return null;
166	    }
167	
168	    private List<Location> getFreeAdjacentLocations(Field field, List<Location> adjacentLocations)
169	    {
170	        List<Location> free = new LinkedList<>();
171	        for(Location location : adjacentLocations) {
172	            if(field.getObjectAt(location) == null) {
173	                free.add(location);
174	            }
175	        }
176	        return free;
177	    }
178	
179	    private List<Location> findAdjacentLocationsWithSpecies(Field field,
180	            List<Location> adjacentLocations,
181	            Class<?> speciesClass)
182	    {
183	        List<Location> matches = new ArrayList<>();
184	        for(Location location : adjacentLocations) {
185	            Object occupant = field.getObjectAt(location);
186	            if(occupant != null && occupant.getClass() == speciesClass) {
187	                matches.add(location);
188	            }
189	        }
190	        return matches;
191	    }
192	
193	    private List<Location> getFreePatches(Field field)
194	    {
195	        List<Location> freePatches = new ArrayList<>();
196	        for(int row = 0; row < field.getDepth(); row++) {
197	            for(int col = 0; col < field.getWidth(); col++) {
198	                Location center = new Location(row, col);
199	                if(field.getObjectAt(center) == null && isPatchFree(field, center)) {
200	                    freePatches.add(center);
201	                }
202	            }
203	        }
204	        return freePatches;
205	    }
206	
207	    private boolean isPatchFree(Field field, Location center)
208	    {
209	        for(Location location : getAdjacentLocations(field, center)) {
210	            if(field.getObjectAt(location) != null) {
211	                return false;
212	            }
213	        }
214	        return true;
215	    }
216	
217	    private Location pickRandomLocation(List<Location> locations)
218	    {
219	        if(locations.isEmpty()) {
220	            return null;
221	        }
222	        return locations.get(randomProvider.getRandom().nextInt(locations.size()));
223	    }
224	
225	    private Location firstOrNull(List<Location> locations)
226	    {
227	        if(locations.isEmpty()) {
228	            return null;
229	        }
230	        return locations.get(0);
231	    }
232	
233	    public record MovementDecision(Location targetLocation, Organism consumedOrganism, boolean overcrowded) { }
234	
235	    private record MovementRule(Class<? extends Organism> fallbackSpecies, ForageRule forageRule)
236	    {
237	        private boolean canForage(Environment environment)
238	        {
239	            return forageRule.canForage(environment);
240	        }
241	    }
242	
243	    @FunctionalInterface
244	    private interface ForageRule
245	    {
246	        boolean canForage(Environment environment);
247	    }
248	
249	    private MovementRule getMovementRule(Class<? extends Organism> organismClass)
250	    {
251	        return movementRules.getOrDefault(organismClass, new MovementRule(DEFAULT_FALLBACK_SPECIES, environment -> true));
252	    }
253	}

