  6	/**
  7	 * A class representing shared characteristics of animals.
  8	 *
  9	 * @version 2022.03.02
 10	 */
 11	public abstract class Animal extends Organism implements Actor
 12	{
 13	    protected int age;
 14	    protected boolean isNocturnal;
 15	    protected int foodLevel;
 16	    protected Gender sex;
 17	
 18	    // An animal is either male or female 
 19	    protected enum Gender {
 20	        MALE,
 21	        FEMALE
 22	    }
 23	
 24	
 25	    // Declaring abstract methods to obtain fields used by subclasses
 26	    // These methods have been declared in order to use common methods in the Animal class, reducing repeatability
 27	    protected abstract int getBreedingAge();
 28	    protected abstract int getMaxLitterSize();
 29	    protected abstract double getBreedingProbability();
 30	    protected abstract int getMaxAge();
 31	    protected abstract int getMaxFoodLevel();
 32	    protected abstract Set<Class<? extends Organism>> getDiet();
 33	
