 35	    /**
 36	     * Create a new animal at location in field.
 37	     *
 38	     * @param field The field currently occupied.
 39	     * @param location The location within the field.
 40	     * @param randomAge The animal's random starting age.
 41	     * @param sex The animal's gender. 
 42	     */
 43	    public Animal(RandomProvider randomProvider, Field field, Location location, boolean randomAge, Gender sex)
 44	    {
 45	        super(randomProvider, field, location);
 46	        this.sex = sex;
 47	        Random rand = getRandomProvider().getRandom();
 48	        if(randomAge) {
 49	            this.age = rand.nextInt(getMaxAge());
 50	            foodLevel = rand.nextInt(getMaxFoodLevel());
 51	        }
 52	        else {
 53	            this.age = 0;
 54	            foodLevel = getMaxFoodLevel();
 55	        }
 56	    }
 57	
 58	    /**
 59	     * Make this animal act - that is: make it do
 60	     * whatever it wants/needs to do.
 61	     * @param newAnimals A list to receive newly born animals.
 62	     * @param environment The environment that the animal resides in.
 63	     */
 64	    public void act(List<Actor> newAnimals, Environment environment)
 65	    {
 66	        incrementAge();
 67	        incrementHunger();
 68	        if(isAlive()) {
 69	            giveBirth(newAnimals, environment);
 70	            move(environment);
 71	        }
 72	    }
 73	
 74	    /**
 75	     * Look for food adjacent to the current location.
 76	     * Only the first food is eaten.
 77	     * @return Where food was found, or null if it wasn't.
 78	     */
 79	    protected MovementService.MovementDecision findFood(Environment environment)
 80	    {
 81	        Field field = getField();
 82	        MovementService movementService = field.getMovementService();
 83	        DiseaseService diseaseService = field.getDiseaseService();
 84	        List<Location> adjacent = movementService.getAdjacentLocations(field, getLocation());
 85	        diseaseService.applyAdjacentExposure(this, adjacent, field);
 86	        return movementService.resolveAnimalMovement(this, environment, adjacent);
 87	    }
 88	
 89	    /**
 90	     * Check whether this animal is to give birth at this step.
 91	     * New births will be made into free adjacent locations.
 92	     * @param newAnimals A list to return newly born animals.
 93	     * @param environment The environment that the animal resides in. 
 94	     */
 95	    protected void giveBirth(List<Actor> newAnimals, Environment environment)
 96	    {
 97	        Field field = getField();
 98	        List<Location> free = field.getMovementService().getFreeAdjacentLocations(field, getLocation());
 99	        int births = breed();
100	        for(int b = 0; b < births && !free.isEmpty(); b++) {
101	            Location loc = free.remove(0);
102	            Gender sex = getRandomProvider().getRandom().nextBoolean() ? Gender.MALE : Gender.FEMALE;
103	            newAnimals.add(createYoung(field, loc, sex));
104	        }
105	    }
106	
107	    protected Animal createYoung(Field field, Location location, Gender sex)
108	    {
109	        return field.getOrganismFactory().createOffspring(getClass().asSubclass(Animal.class), field, location, sex);
110	    }
111	
112	    /**
113	     * Returns true if the animal is awake or not.
114	     */
115	    public boolean isAwake(Environment environment)
116	    {
117	        if(isNocturnal){
118	            return !environment.getTime().isDay();
119	        }
120	        return environment.getTime().isDay();
121	    }
122	
123	    /**
124	     * Generates a number representing the number of births,
125	     * if it can breed.
126	     * @return The number of births (may be zero)
127	     */
128	    protected int breed()
129	    {
130	        Random rand = getRandomProvider().getRandom();
131	        int births = 0;
132	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
133	            births = rand.nextInt(getMaxLitterSize()) + 1;
134	            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
135	            getField().getDiseaseService().applySexualExposure(this, mate);
136	        }
137	        return births;
138	    }
139	
140	    /**
141	     * Returns true if the animal is able to breed.
142	     * Returns false if otherwise. 
143	     */
144	    protected boolean canBreed()
145	    {
146	        return age >= getBreedingAge() && !getPotentialMates().isEmpty();
147	    }
148	
149	    /**
150	     * Returns a list of potential mates. Mates have to be
151	     * of a opposite gender. 
152	     * @return List<Organism> A list of potential mates.
153	     */
154	    protected List<Organism> getPotentialMates()
155	    {
156	        if(getField() != null){
157	            return getField().getMovementService().findPotentialMates(this);
158	        }
159	        return new ArrayList<>();
160	    }
161	
162	
163	    /**
164	     * Increase the age. This could result in the animal's death.
165	     */
166	    protected void incrementAge()
167	    {
168	        this.age++;
